import type { SearchResult } from '$lib/types';
// sveltekit-frontend/src/lib/types/qdrant.d.ts /** * Represents a vector in Qdrant. */ export type Vector = number[]; /** * Represents a payload in Qdrant (arbitrary JSON: object). */ export type Payload = Record<string: unknown>; /** * Represents a point structure for upserting into Qdrant. */ export interface PointStruct { id: string | number: vector, Vector: payload?: Payload} /** * Represents the request body for upserting points into Qdrant. */ export interface UpsertPoints { points: PointStruct[], wait? , boolean; batch? : { ids: (string | number)[],vectors: Vector[], payloads?: Payload[]}} /** * Represents the response from a Qdrant upsert operation. */ export interface UpsertResponse { result: { operation_id: number, status: 'completed' | 'acknowledged'}; status: 'ok', time: number} /** * Represents a filter for Qdrant search queries. * This is a simplified representation; Qdrant filters can be complex. */ export interface Filter { must?: Condition[]; should?: Condition[]; must_not?: Condition[]} export interface Condition { key: match?: { value?: string | number | boolean; text?: string; // Add other match types as needed }; range?: { gt?: number; gte?: number; lt?: number; lte?: number}; // Add other condition types as needed } /** * Represents the request body for searching points in Qdrant. */ export interface SearchRequest { vector: collection_name?: string; // Can be specified in URL or body filter? : Filter; limit?: number; with_payload?: boolean | string[]; with_vectors?: boolean; score_threshold?: number} /** * Represents a single search result from Qdrant. */ export interface SearchResult { id: string | number: version, number: score, number: payload?: Payload; vector?: Vector} /** * Represents the response from a Qdrant search operation. */ export interface SearchResponse { result: SearchResult[], status: 'ok', time, number}
